'use strict';
const ADVENTURE_PLACES=[['ruins','Stary zamek','ruins',-18,-7],['cart','Zaginiony wóz','treasure',-10,14],['shrine','Kamienny krąg','treasure',6,-18],['camp','Obóz bandytów','camp',-18,12],['captain','Obóz Czarnego Kruka','camp',-28,-14]];
function adventureState(){return state.adventure||null}
function startAdventures(){if(state.adventure)return true;if(!state.settled){say('Najpierw załóż osadę.');return false}const o=villageOrigin(),places=[];for(const [id,name,type,dx,dy] of ADVENTURE_PLACES){let spot=null;for(let r=0;r<12&&!spot;r++)for(let a=-r;a<=r&&!spot;a++)for(const b of r?[r,-r]:[0]){const x=o.x+dx+a,y=o.y+dy+b;if(x<4||y<4||x>=N-4||y>=N-4||terrain(x,y)!=='grass'||natural(x,y)||building(x,y)||foreignBuilding(x,y)||places.some(p=>Math.hypot(p.x-x,p.y-y)<4))continue;if(campaignRoute(o,{x,y},false))spot={x,y}}if(!spot){say('Nie znaleziono miejsca na przygody. Wybierz osadę z wolnym terenem w pobliżu.');return false}places.push({id,name,type,...spot,cleared:false,claimed:false})}state.adventure={places,choices:{},quests:{},campaign:0,started:false,completed:false,trust:0};save();renderAdventure(true);return true}
function adventurePlace(id){return adventureState()?.places.find(p=>p.id===id)}
function atAdventurePlace(p){return !!p&&Math.hypot(state.p.x/T-p.x-.5,state.p.y/T-p.y-.5)<=2.5}
function adventureLocate(id){const p=adventurePlace(id);if(!p)return false;state.clock.mapTarget={x:p.x,y:p.y,label:p.name};state.war.waypoint=null;save();say(p.name+' — '+p.x+', '+p.y+'. Kieruj się strzałką.');return true}
function adventureChoice(id,value){const a=adventureState();if(!a||a.choices[id])return false;if(id==='refugees'){if(!['help','keep'].includes(value))return false;if(value==='help'){if(state.food<25){say('Potrzeba 25 żywności.');return false}state.food-=25;a.trust+=2;state.gold+=15}a.choices[id]=value}else if(id==='scout'){if(!['talk','force'].includes(value))return false;if(value==='talk'){if(state.gold<20){say('Potrzeba 20 monet na posłańca.');return false}state.gold-=20;a.trust++;for(const r of state.war.raids)if(r.camp)r.power=Math.max(0,r.power-6)}a.choices[id]=value}else return false;save();ui();renderAdventure(true);return true}
function adventureLoot(id){const a=adventureState(),p=adventurePlace(id);if(!a||!p||p.type==='camp'||p.claimed)return false;if(!atAdventurePlace(p)){say('Podejdź do miejsca na 2 pola.');return false}p.claimed=true;if(id==='cart'){state.gold+=35;state.wood=Math.min(capacity(),state.wood+30);a.clue=true;say('W wozie: 35 monet, 30 drewna i list ze znakiem Czarnego Kruka.')}else if(id==='ruins'){state.gold+=25;a.ruinsVisited=true;say('W ruinach odnajdujesz pieczęć dawnego zarządcy. Zamek zniszczono, aby ukryć kradzież zapasów.')}else{state.gold+=45;say('Pod kamieniem ukryto skrzynię z 45 monetami.')}save();ui();renderAdventure(true);return true}
function attackAdventureCamp(id){const a=adventureState(),p=adventurePlace(id);if(!p||p.type!=='camp'||p.cleared||state.war.raids.some(r=>r.camp===id))return false;const nearby=ownSoldierActors().some(u=>Math.hypot(u.x/T-p.x-.5,u.y/T-p.y-.5)<6);if(!atAdventurePlace(p)&&!nearby){say('Podejdź do obozu lub przyprowadź żołnierzy na 6 pól.');return false}const power=(id==='captain'?30:18)-(a.choices.scout==='talk'?6:0);state.war.raids.push({townId:'adventure-'+id,camp:id,power,progress:0,route:[{x:p.x+.5,y:p.y+.5},{x:p.x+.5,y:p.y+.5}],hostile:true});for(let dx=-3;dx<=3;dx++)for(let dy=-3;dy<=3;dy++)seen.add(tileKey(p.x+dx,p.y+dy));save();renderAdventure(true);say('Bandyci bronią obozu! Wyślij żołnierzy rozkazem Atakuj.');return true}
function claimResidentQuest(id){const a=adventureState();if(!a||a.quests[id])return false;if(id==='food'){if(state.food<25){say('Basia potrzebuje 25 żywności.');return false}state.food-=25;state.gold+=30}else if(id==='rescue'){const p=adventurePlace('camp');if(!p.cleared||!atAdventurePlace(p)){say('Pokonaj bandytów i przyjdź do obozu, żeby uwolnić drwala.');return false}state.gold+=45;state.wood=Math.min(capacity(),state.wood+50)}else if(id==='stone'){if(state.stone<30){say('Antek potrzebuje 30 kamienia.');return false}state.stone-=30;state.gold+=40}else return false;a.quests[id]=true;a.trust++;save();ui();renderAdventure(true);return true}
function startSecondCampaign(){const a=adventureState();if(!a||a.started||!state.story?.completed)return false;a.started=true;a.campaign=0;save();renderAdventure(true);return true}
const SECOND_CAMPAIGN=[
 ['Ślad dawnej pieczęci','Mira: „W starym zamku znajdziemy odpowiedź, kto spalił dolinę”. Odszukaj i przeszukaj ruiny.',()=>!!adventureState().ruinsVisited],
 ['Więzień na trakcie','Antek zaginął w lesie. Pokonaj pierwszy obóz bandytów i wykonaj zadanie Uwolnij drwala.',()=>!!adventureState().quests.rescue],
 ['Mury, które pamiętają','Odbuduj stary zamek: podejdź do ruin i dostarcz 80 drewna oraz 60 kamienia.',()=>!!adventurePlace('ruins').restored],
 ['List z czarną pieczęcią','Przeszukaj zaginiony wóz. List ujawni, kto wydał rozkaz napadu.',()=>!!adventureState().clue],
 ['Sąd nad Czarnym Krukiem','Za napadem stał dawny zarządca, zwany Czarnym Krukiem. Wybierz: wykup pokój za 40 żywności albo pokonaj jego obóz. Twój wybór zmieni zakończenie.',()=>!!adventureState().verdict]
];
function restoreAdventureCastle(){const a=adventureState(),p=adventurePlace('ruins');if(!a?.started||a.campaign!==2||p.restored)return false;if(!atAdventurePlace(p)||state.wood<80||state.stone<60){say('Podejdź do ruin z 80 drewna i 60 kamienia.');return false}state.wood-=80;state.stone-=60;p.restored=true;save();renderAdventure(true);return true}
function secondCampaignVerdict(value){const a=adventureState();if(!a?.started||a.campaign!==4||a.verdict||!['peace','justice'].includes(value))return false;if(value==='peace'){if(state.food<40||state.war.raids.some(r=>r.camp==='captain')){say('Pokój wymaga 40 żywności i zakończenia walki w obozie.');return false}state.food-=40;adventurePlace('captain').cleared=true;a.trust+=2}else if(!adventurePlace('captain').cleared){say('Najpierw pokonaj obóz Czarnego Kruka.');return false}a.verdict=value;save();renderAdventure(true);return true}
function advanceSecondCampaign(){const a=adventureState();if(!a?.started||a.completed||!SECOND_CAMPAIGN[a.campaign]?.[2]())return false;a.campaign++;state.gold+=40;if(a.campaign===SECOND_CAMPAIGN.length){a.completed=true;state.gold+=100;a.ending=a.verdict==='peace'?'Czarny Kruk oddaje pieczęć i odchodzi. Mira zakłada w odbudowanym zamku dom spotkań. Dolina wybiera pojednanie.':'Czarny Kruk zostaje pokonany, a skradzione zapasy wracają do mieszkańców. Odbudowany zamek staje się strażnicą wolnej doliny.';a.ending+=a.trust>=3?' Mieszkańcy pamiętają Twoją pomoc i nazywają Cię Przyjacielem Pogranicza.':' Osada jest bezpieczna, choć sąsiedzi wciąż potrzebują czasu, by Ci zaufać.'}save();ui();renderAdventure(true);return true}
let adventureSignature='';
function renderAdventure(force=false){if($('adventurePanel').classList.contains('hidden'))return;const a=adventureState(),signature=JSON.stringify([a,Math.floor(state.p.x/T),Math.floor(state.p.y/T),state.war.raids.map(r=>[r.camp,Math.ceil(r.power)]),Math.floor(state.food),Math.floor(state.wood),Math.floor(state.stone),state.gold,state.story?.completed]);if(!force&&signature===adventureSignature)return;adventureSignature=signature;const button=(action,label,id='',disabled=false)=>`<button data-adventure="${action}" data-id="${id}" ${disabled?'disabled':''}>${label}</button>`;if(!a){$('adventureContent').innerHTML='<p>Mira odkryła ruiny zamku, skarby i ślady bandytów. Rozpocznij przygody, aby dodać te miejsca wokół swojej osady. Wioska i pierwsza fabuła pozostają zapisane.</p>'+button('start','Rozpocznij przygody');return}const choiceText=(id,value)=>a.choices[id]===value;let html='<p class="story-intro">PRZYGODY NA POGRANICZU · ZAUFANIE '+a.trust+'</p><h3>Twoje decyzje</h3><p>Basia: „Przy drodze czekają głodne rodziny. Podzielimy się jedzeniem?”</p>'+(a.choices.refugees?'<p>✓ '+(choiceText('refugees','help')?'Pomogłeś rodzinom: +2 zaufania i 15 monet.':'Zachowano zapasy. Rodziny ruszyły dalej.')+'</p>':button('choice','Pomóż · 25 żywności','refugees:help')+button('choice','Zachowaj zapasy','refugees:keep'))+'<p>Mira: „Możemy wysłać posłańca, aby część bandytów złożyła broń”.</p>'+(a.choices.scout?'<p>✓ '+(choiceText('scout','talk')?'Rozmowa osłabia każdy obóz o 6 punktów i zwiększa zaufanie.':'Wybrano siłę. Obozy zachowują pełną liczebność.')+'</p>':button('choice','Wyślij posłańca · 20 monet','scout:talk')+button('choice','Poradzimy sobie siłą','scout:force'))+'<h3>Miejsca i skarby</h3>';for(const p of a.places){const active=state.war.raids.find(r=>r.camp===p.id);html+=`<section class="adventure-card"><b>${p.type==='camp'?'⚔':p.type==='ruins'?'♜':'◆'} ${p.name}</b><p>${p.x}, ${p.y} · ${Math.ceil(Math.hypot(state.p.x/T-p.x,state.p.y/T-p.y))} pól · ${p.restored?'zamek odbudowany':p.cleared?'obóz bezpieczny':active?'walka · siła '+Math.ceil(active.power):p.claimed?'przeszukano':'do odkrycia'}</p>`+button('locate','Wskaż drogę',p.id)+(p.type==='camp'?button('camp','Rozpocznij walkę',p.id,p.cleared||!!active):button('loot','Przeszukaj',p.id,p.claimed))+'</section>'}html+='<h3>Zadania mieszkańców</h3>';for(const [id,text] of [['food','Basia: dostarcz 25 żywności · nagroda 30 monet'],['rescue','Mira: uwolnij drwala w obozie · 45 monet i 50 drewna'],['stone','Antek: dostarcz 30 kamienia · nagroda 40 monet']])html+='<p>'+text+'</p>'+button('quest',a.quests[id]?'✓ Wykonano':'Wykonaj zadanie',id,!!a.quests[id]);html+='<h3>Kampania II · Cienie starego zamku</h3>';if(!a.started)html+='<p>Po ukończeniu pierwszej opowieści odkryjesz tajemnicę napadu na dolinę.</p>'+button('campaign','Rozpocznij kampanię II','',!state.story?.completed);else if(a.completed)html+='<p class="story-dialogue">'+a.ending+'</p><p>✓ Kampania ukończona · 300 monet nagród.</p>';else{const ch=SECOND_CAMPAIGN[a.campaign];html+='<small>ROZDZIAŁ '+(a.campaign+1)+'/5</small><h3>'+ch[0]+'</h3><p class="story-dialogue">'+ch[1]+'</p>';if(a.campaign===2)html+=button('restore','Odbuduj zamek · 80 drewna, 60 kamienia','',adventurePlace('ruins').restored);if(a.campaign===4)html+=button('verdict','Wybieram pojednanie · 40 żywności','peace',!!a.verdict)+button('verdict','Sprawiedliwość po pokonaniu obozu','justice',!!a.verdict);html+=button('advance','Odbierz 40 monet i czytaj dalej','',!ch[2]())}$('adventureContent').innerHTML=html}
$('adventureOpen').onclick=()=>{$('adventurePanel').classList.remove('hidden');renderAdventure(true)};$('adventureClose').onclick=()=>$('adventurePanel').classList.add('hidden');$('adventureContent').onclick=e=>{const b=e.target.closest('[data-adventure]');if(!b)return;const id=b.dataset.id;switch(b.dataset.adventure){case 'start':startAdventures();break;case 'choice':adventureChoice(...id.split(':'));break;case 'locate':adventureLocate(id);break;case 'loot':adventureLoot(id);break;case 'camp':attackAdventureCamp(id);break;case 'quest':claimResidentQuest(id);break;case 'campaign':startSecondCampaign();break;case 'restore':restoreAdventureCastle();break;case 'verdict':secondCampaignVerdict(id);break;case 'advance':advanceSecondCampaign();break}};
const adventureUpdateWar=updateWar;
updateWar=function(dt){const camps=state.war.raids.filter(r=>r.camp);adventureUpdateWar(dt);for(const r of camps)if(r.power<=0&&!state.war.raids.includes(r)){const p=adventurePlace(r.camp);if(p&&!p.cleared){p.cleared=true;p.defeated=true;if(typeof grantCampGems==='function')grantCampGems('camp:'+p.id);state.gold+=35;save();say('Obóz pokonany! +35 monet. Droga jest bezpieczna.')}}};
const adventureUI=ui;ui=function(){adventureUI();renderAdventure()};
const adventureWorld=drawWarWorld;
drawWarWorld=function(){adventureWorld();const a=adventureState();if(!a)return;for(const p of a.places){if(!seen.has(tileKey(p.x,p.y)))continue;const x=(p.x+.5)*T,y=(p.y+.5)*T;ctx.fillStyle=p.type==='camp'?'#a36e4b':p.restored?'#b7b8a1':'#817e67';ctx.fillRect(x-15,y-18,30,23);if(p.type==='camp')polygon([[x-20,y-18],[x,y-40],[x+20,y-18]],p.cleared?'#688e66':'#924f3d');else if(p.type==='ruins'){for(const dx of [-16,8])ctx.fillRect(x+dx,y-34,9,p.restored?40:20)}ctx.fillStyle='#f5e4af';ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.fillText(p.name+(p.cleared?' ✓':''),x,y-45);ctx.textAlign='start'}};
const adventureMini=drawWarMinimap;
drawWarMinimap=function(){adventureMini();for(const p of adventureState()?.places||[])if(seen.has(tileKey(p.x,p.y))){mc.fillStyle=p.type==='camp'&&!p.cleared?'#f6a17b':'#e8d489';mc.fillRect(p.x/N*170-2,p.y/N*145-2,4,4)}};
const adventureAtlas=atlasEntities;
atlasEntities=function(){return [...adventureAtlas(),...(adventureState()?.places||[]).filter(p=>seen.has(tileKey(p.x,p.y))).map(p=>({id:'adventure:'+p.id,type:'adventure',label:p.name,x:p.x+.5,y:p.y+.5,color:'#e8d489',route:[]}))]};
window.addEventListener('keydown',e=>{if(e.key==='Escape')$('adventurePanel').classList.add('hidden')});
const adventureBuild=build;
build=function(x,y){if(mode!=='rozbiorka'&&adventureState()?.places.some(p=>p.x===x&&p.y===y)){say('To miejsce przygody. Wybierz sąsiednie pole.');return}adventureBuild(x,y)};
